// Generate a fuzzed narrow string input. Lifetime spans the call via local variable.
std::string s = FUZZ_PARAM_STR();

// Call the conversion function. It may allocate; guard against allocation failure.
try {
    std::wstring ws = String2WString(s);

    // Enforce a minimal semantic: empty input should reasonably produce empty output.
    if (s.empty() && !ws.empty()) { FUZZ_BAIL(); }

    // Touch result to keep it live and exercise access paths without assumptions on encoding.
    if (!ws.empty()) {
        volatile wchar_t ch = ws[0];
        (void)ch;
    }
} catch (const std::bad_alloc&) {
    // If conversion allocates and fails, bail to keep harness stable.
    FUZZ_BAIL();
} catch (...) {
    // Implementation-specific exceptions (locale/encoding issues, etc.) are treated as bail conditions
    // to avoid undefined harness behavior.
    FUZZ_BAIL();
}

// Validation: No inputs/outputs from the object pool are required; we generate the std::string locally
// and do not expose the returned std::wstring as a persistent object. Error paths bail appropriately.
